"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["4687"],{4832(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>u,frontMatter:()=>r,contentTitle:()=>h,toc:()=>c,assets:()=>d});var a=JSON.parse('{"id":"m5-plan-execute-verify/lesson","title":"Plan, Execute, Verify","description":"Module 1 gave you a loop you state what the task is before the agent touches anything, you review the plan before it edits, you run the change in a place where a mistake costs nothing, and you let the repository decide whether the work is done rather than asking the agent to grade its own homework.","source":"@site/docs/m5-plan-execute-verify/lesson.md","sourceDirName":"m5-plan-execute-verify","slug":"/m5-plan-execute-verify/lesson","permalink":"/306-agentic-devops-claude/docs/m5-plan-execute-verify/lesson","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Plan, Execute, Verify"},"sidebar":"courseSidebar","previous":{"title":"Deep Dive (Part 2)","permalink":"/306-agentic-devops-claude/docs/m4-model-effort-cost/deep-dive"},"next":{"title":"Lab: A Change Under Contract","permalink":"/306-agentic-devops-claude/docs/m5-plan-execute-verify/lab"}}'),s=n(4848),i=n(8453),o=n(7684);let r={sidebar_position:1,title:"Plan, Execute, Verify"},h="Plan, Execute, Verify",d={},c=[{value:"Why you write the task down before the agent runs",id:"why-you-write-the-task-down-before-the-agent-runs",level:2},{value:"Plan mode: separate thinking from acting",id:"plan-mode-separate-thinking-from-acting",level:2},{value:"Isolate the work: worktrees, checkpoints, rewind",id:"isolate-the-work-worktrees-checkpoints-rewind",level:2},{value:"Verification the repository owns, not the agent infers",id:"verification-the-repository-owns-not-the-agent-infers",level:2},{value:"What &quot;done&quot; actually means",id:"what-done-actually-means",level:2},{value:"What you&#39;ll do in the lab",id:"what-youll-do-in-the-lab",level:2}];function l(e){let t={admonition:"admonition",code:"code",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(o.A,{src:"decks/m5-plan-execute-verify.html",title:"M5: Plan, Execute, Verify"}),"\n",(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"plan-execute-verify",children:"Plan, Execute, Verify"})}),"\n",(0,s.jsxs)(t.p,{children:["Module 1 gave you a loop: diagnose, change, verify. It was deliberately loose, because the bug was one wrong word and the point was to build the habit. This module takes that same loop and makes it rigorous enough to run against a system you cannot afford to break. The change is small again, a low-risk application tweak, but everything around it is formalized: you state what the task is ",(0,s.jsx)(t.em,{children:"before"})," the agent touches anything, you review the plan ",(0,s.jsx)(t.em,{children:"before"})," it edits, you run the change in a place where a mistake costs nothing, and you let the ",(0,s.jsx)(t.em,{children:"repository"})," decide whether the work is done rather than asking the agent to grade its own homework."]}),"\n",(0,s.jsxs)(t.p,{children:['Here is the gap this closes. In Module 1 you were in the loop the whole time: reading each step, approving each edit, watching the verify. That works when you are babysitting one small fix. It does not scale, and it does not survive the moment you hand a task to an agent and step away. The instant the agent has any autonomy, three questions become load-bearing: did it understand what it was actually asked to do, did it stay inside the lines, and is "done" a fact or the agent\'s opinion? A loose loop answers none of these. This module turns each into a written, checkable artifact: a ',(0,s.jsx)(t.strong,{children:"task contract"}),", a ",(0,s.jsx)(t.strong,{children:"reviewed plan"}),", an ",(0,s.jsx)(t.strong,{children:"isolated workspace"}),", and ",(0,s.jsx)(t.strong,{children:"repository-owned verification"}),", so that the loop holds even when you are not watching every step."]}),"\n",(0,s.jsx)(t.h2,{id:"why-you-write-the-task-down-before-the-agent-runs",children:"Why you write the task down before the agent runs"}),"\n",(0,s.jsxs)(t.p,{children:['Think about how a good change ticket works on a team that has been burned. It does not just say "fix the thing." It says what the change is for, which systems it touches, which environment it lands in, what counts as success, and what to do if it goes wrong. The ticket exists because "I thought you meant the staging database" is an expensive sentence, and the cheapest place to catch that misunderstanding is ',(0,s.jsx)(t.em,{children:"before"})," anyone opens an editor."]}),"\n",(0,s.jsxs)(t.p,{children:["An agent needs that same ticket, and for a sharper reason: the agent will do ",(0,s.jsx)(t.em,{children:"exactly"}),' what it inferred you meant, quickly, without the pause where a human colleague would say "wait, do you really want me touching production for this?" The agent\'s speed is the whole value and the whole danger. So you front-load the agreement. You write down the task as a ',(0,s.jsx)(t.strong,{children:"contract"}),", a structured statement of intent, scope, and acceptance that both you and the agent work from, and you do it before execution, when changing your mind is free."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Analogy:"})," a task contract is a flight plan filed before takeoff. A pilot does not improvise the route mid-air. Before the engines start, the plan states the destination, the corridor, the fuel, the alternates, and the abort conditions, and it is reviewed on the ground where changing it costs nothing. Once airborne, the plan is the reference everyone flies against, and deviating from it is a deliberate, visible act, not a drift nobody noticed. The task contract is that filed plan for an agent run: agreed before the work, referenced during it, and a deviation from it is something you can ",(0,s.jsx)(t.em,{children:"see"}),"."]}),"\n",(0,s.jsx)(t.p,{children:"A task contract has a fixed structure. Every field answers a question that, left unanswered, is where autonomous runs go wrong:"}),"\n",(0,s.jsx)(t.pre,{children:(0,s.jsx)(t.code,{className:"language-yaml",children:'task:\n  intent: "Add a /version endpoint to orders-api so ops can confirm the deployed build"\n  target: "app/orders-api/ only"\n  environment: "dev"\n  actions:\n    allowed: ["read app/", "edit app/orders-api/", "run tests"]\n    denied: ["modify infra/", "docker push", "kubectl apply", "edit other services"]\n  acceptance:\n    - "All existing tests still pass"\n    - "A new test covers the /version endpoint"\n    - "grade.sh m5 returns PASS"\n  stop_conditions:\n    - "3 failed attempts to make tests pass \u2192 stop and escalate"\n    - "Change would touch a file outside app/orders-api/ \u2192 stop and ask"\n    - "Token budget exceeded \u2192 checkpoint and stop"\n  rollback: "git checkout main -- app/orders-api/"\n'})}),"\n",(0,s.jsxs)(t.p,{children:["Read down the fields and notice that none of them are about ",(0,s.jsx)(t.em,{children:"how"})," to write the code. That is the agent's job. They are about the ",(0,s.jsx)(t.strong,{children:"boundary and the definition of success"}),", which is yours. ",(0,s.jsx)(t.code,{children:"intent"})," keeps the agent solving the right problem. ",(0,s.jsx)(t.code,{children:"target"})," and ",(0,s.jsx)(t.code,{children:"actions"})," are the leash from Module 2, restated per task. ",(0,s.jsx)(t.code,{children:"acceptance"})," is the thing most people leave implicit and then argue about: what, precisely, makes this done. ",(0,s.jsx)(t.code,{children:"stop_conditions"})," are the abort criteria: the moments where the correct move is to ",(0,s.jsx)(t.em,{children:"stop"}),", not to push through. ",(0,s.jsx)(t.code,{children:"rollback"}),' is the answer to "and if it\'s wrong?" written down while you are calm, not improvised during an incident.']}),"\n",(0,s.jsx)(t.admonition,{title:"The contract is per-task; the settings are per-session",type:"note",children:(0,s.jsxs)(t.p,{children:["Module 2's ",(0,s.jsx)(t.code,{children:"settings.json"})," permissions are a standing boundary that applies to every run in the workspace. The task contract is narrower and sharper: it is the boundary and success criteria for ",(0,s.jsx)(t.em,{children:"this one task"}),". They stack: the contract can only tighten what settings already allow, never loosen it. Think of settings as the building's locked doors and the contract as the specific room you are authorized to work in today."]})}),"\n",(0,s.jsx)(t.h2,{id:"plan-mode-separate-thinking-from-acting",children:"Plan mode: separate thinking from acting"}),"\n",(0,s.jsxs)(t.p,{children:['Even with a contract, there is a moment of maximum risk: the transition from "the agent understands the task" to "the agent is editing files." In a loose loop those are fused: the agent reasons and edits in one motion, and you find out what it decided by watching the diffs appear. That is fine for a one-word fix. It is not fine when the change is large enough that a wrong ',(0,s.jsx)(t.em,{children:"approach"}),", not a wrong line, a wrong whole strategy, is expensive to unwind."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Analogy:"})," plan mode is the surgeon's pre-op briefing. Before the first incision, the surgeon walks the team through the procedure: this is what we will do, in this order, these are the structures we will avoid, here is where we expect trouble. The point of the briefing is that it happens while the patient is still closed: objections are cheap, the plan can change, nobody has cut anything. Executing without a briefing is not braver; it is just moving the discovery of a bad plan to the worst possible time. Plan mode is that briefing for an agent: it explores and produces the procedure, and you approve it, before any edit is made."]}),"\n",(0,s.jsxs)(t.p,{children:["Concretely, plan mode is a permission mode where the agent can read, search, and reason, but ",(0,s.jsx)(t.strong,{children:"cannot edit files or run mutating commands."})," It produces a plan: here is what I found, here is what I will change, here is the order. You read that plan against your contract. Does the approach match the intent? Does it stay inside ",(0,s.jsx)(t.code,{children:"target"}),"? Does it trip any ",(0,s.jsx)(t.code,{children:"stop_condition"}),"? Only when the plan is right do you switch to execution."]}),"\n",(0,s.jsx)(t.mermaid,{value:'flowchart LR\n    CONTRACT["Task contract<br/>intent \xb7 target \xb7 actions<br/>acceptance \xb7 stop \xb7 rollback"] --\x3e PLAN["Plan mode<br/>agent reads + reasons<br/><b>cannot edit</b>"]\n    PLAN --\x3e REVIEW{"Plan matches<br/>the contract?"}\n    REVIEW --\x3e|"no, wrong approach"| PLAN\n    REVIEW --\x3e|"yes"| EXEC["Execute<br/>agent edits inside target"]\n    EXEC --\x3e VERIFY["Repository-owned<br/>verification"]\n    VERIFY --\x3e|"red"| EXEC\n    VERIFY --\x3e|"green"| DONE["Done<br/>evidence + rollback + receipt"]'}),"\n",(0,s.jsxs)(t.p,{children:["The value of plan mode is not that it catches typos. Verification does that. It catches the agent about to solve the problem the ",(0,s.jsx)(t.em,{children:"wrong way"}),": adding a dependency you did not want, editing three files when the contract said one, choosing an approach that technically works but that you will regret. Those are cheap to fix in a plan and expensive to fix in a diff."]}),"\n",(0,s.jsx)(t.h2,{id:"isolate-the-work-worktrees-checkpoints-rewind",children:"Isolate the work: worktrees, checkpoints, rewind"}),"\n",(0,s.jsxs)(t.p,{children:["The contract says where the agent may work; plan mode lets you approve the approach. The third layer is ",(0,s.jsx)(t.em,{children:"where the execution physically happens"}),", because even a reviewed plan executed by a fast agent should not run directly on the branch you care about."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Analogy:"})," a worktree is a rehearsal stage built off to the side. The main stage, your ",(0,s.jsx)(t.code,{children:"main"})," branch, is where the real show runs, and you do not rehearse a risky new number on it while the audience is seated. You build an identical stage in the wings, rehearse there as roughly as you need, and only bring the number to the main stage once it is good. If the rehearsal is a disaster, you strike the side stage and the main stage never knew it happened. A git worktree is that side stage: a separate working directory, on its own branch, sharing the same repository, where the agent can work and fail without any of it touching ",(0,s.jsx)(t.code,{children:"main"}),"."]}),"\n",(0,s.jsxs)(t.p,{children:["You create one with a single command, point the agent at it, and let it work. If the change is good, you merge it back. If it is bad, you delete the worktree and there is nothing to clean up: ",(0,s.jsx)(t.code,{children:"main"}),' was never modified. This is the strongest form of the Module 2 boundary: not "the agent is allowed to edit these files" but "the agent is editing a ',(0,s.jsx)(t.em,{children:"disposable copy"}),', and the original is out of reach entirely."']}),"\n",(0,s.jsx)(t.p,{children:"Worktrees are the heavy isolation. Two lighter tools cover the in-flight moments:"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Checkpoints"}),': before a risky step, you commit or stash so there is a named point to return to. A checkpoint is cheap insurance: it costs one command and it means "whatever happens next, I can get back to exactly here." Branches themselves are checkpoints: named, revertable, free.']}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Rewind"}),": Claude Code can roll back the last agent action when it goes wrong, so a bad edit does not require you to reconstruct the previous state by hand. It is the undo for the agent's last move."]}),"\n"]}),"\n",(0,s.jsx)(t.mermaid,{value:'flowchart TD\n    MAIN["main branch<br/>(protected, never edited directly)"]\n    MAIN --\x3e|"git worktree add"| WT["Worktree<br/>(isolated dir, own branch)"]\n    WT --\x3e WORK["Agent executes here"]\n    WORK --\x3e GOOD{"Change<br/>good?"}\n    GOOD --\x3e|"yes"| MERGE["Merge back to main"]\n    GOOD --\x3e|"no"| DROP["Delete worktree<br/>main untouched"]\n    WORK -.->|"bad last step"| REWIND["Rewind / undo<br/>roll back one action"]\n    REWIND --\x3e WORK'}),"\n",(0,s.jsx)(t.p,{children:"These are not three competing tools; they are three depths of the same instinct. Rewind undoes one step. A checkpoint returns you to one saved moment. A worktree keeps the entire experiment off the branch that matters. You reach for the depth that matches the risk of what you are about to let the agent do."}),"\n",(0,s.jsx)(t.h2,{id:"verification-the-repository-owns-not-the-agent-infers",children:"Verification the repository owns, not the agent infers"}),"\n",(0,s.jsx)(t.p,{children:'Now the sharpest idea in the module. You have a contract, an approved plan, and an isolated workspace. The agent has made the change. The last question, the one that decides whether you ship, is "is it done?" And there are two very different ways to answer it.'}),"\n",(0,s.jsxs)(t.p,{children:["The first is to ",(0,s.jsx)(t.strong,{children:"ask the agent."})," Claude Code can look at what it did and tell you whether it thinks the task is complete. This is inference: the same model that wrote the change also judges the change. Sometimes that judgment is right. But it has a structural flaw: the agent is grading its own work using the same understanding that produced the work, so any blind spot in the doing is a blind spot in the checking. If it misunderstood the task, it will confidently confirm it did the misunderstood task correctly."]}),"\n",(0,s.jsxs)(t.p,{children:["The second is to let the ",(0,s.jsx)(t.strong,{children:"repository"})," decide. The acceptance criteria in your contract map to ",(0,s.jsx)(t.em,{children:"automated checks that live in the repo and do not care what the agent thinks"}),": the existing test suite, a new test for the change, a linter, a grading script. You run them. Green is done. Red is not done. The check has no opinion and no blind spot aligned with the agent's, because it was written independently of this run."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Analogy:"})," this is the difference between a student saying \"yeah, I'm pretty sure I passed\" and the graded exam coming back. The student's self-assessment is not worthless, but you do not register them for the next course on the strength of it. You wait for the graded result, because the grade is ",(0,s.jsx)(t.em,{children:"external"}),": it was set by someone other than the person being graded, against a rubric fixed in advance, and it catches exactly the mistakes the student was too confident to notice. Repository-owned verification is the graded exam. ",(0,s.jsx)(t.code,{children:"/verify"}),"-style agent self-assessment is the student's hunch, useful as a quick gut-check, never as the thing you ship on."]}),"\n",(0,s.jsx)(t.mermaid,{value:'flowchart TD\n    CHANGE["Agent made the change"] --\x3e Q{"Is it done?"}\n    Q --\x3e INFER["Agent infers<br/>\'looks complete to me\'"]\n    Q --\x3e REPO["Repository decides<br/>tests \xb7 lint \xb7 grade.sh"]\n    INFER --\x3e RISK["Same understanding that<br/>wrote it now judges it<br/><b>shared blind spot</b>"]\n    REPO --\x3e FACT["Green = done<br/>Red = not done<br/><b>external, reproducible</b>"]'}),"\n",(0,s.jsxs)(t.p,{children:["Why the repository wins is worth stating plainly. Repo-owned checks are ",(0,s.jsx)(t.strong,{children:"reproducible"}),": they give the same verdict on your machine, a teammate's, and in CI, because they are just code. They ",(0,s.jsx)(t.strong,{children:"do not hallucinate"}),": a passing test is a fact about behavior, not a claim about it. And they ",(0,s.jsx)(t.strong,{children:"catch what self-assessment misses"}),": the regression in a neighboring feature, the edge case the agent did not think to consider, precisely because the check was written without this run's blind spots. The pattern is: acceptance criteria in the contract become automated checks in the repo, and green becomes the definition of done. The agent's self-assessment is demoted from ",(0,s.jsx)(t.em,{children:"the verdict"})," to ",(0,s.jsx)(t.em,{children:"a hint on the way to the verdict"}),"."]}),"\n",(0,s.jsx)(t.h2,{id:"what-done-actually-means",children:'What "done" actually means'}),"\n",(0,s.jsx)(t.p,{children:'"The tests pass" is necessary but it is not the whole definition of done for an agent task you might have to defend later. A task you can stand behind, in a review, in a postmortem, to the person who has to trust it went out safely, closes on five things:'}),"\n",(0,s.jsxs)(t.table,{children:[(0,s.jsx)(t.thead,{children:(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.th,{children:"Element"}),(0,s.jsx)(t.th,{children:"The question it answers"}),(0,s.jsx)(t.th,{children:"Where it comes from"})]})}),(0,s.jsxs)(t.tbody,{children:[(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:(0,s.jsx)(t.strong,{children:"Tests pass"})}),(0,s.jsx)(t.td,{children:"Does the change work, and did it break anything?"}),(0,s.jsx)(t.td,{children:"Existing suite + a new test for the change"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:(0,s.jsx)(t.strong,{children:"Evidence"})}),(0,s.jsx)(t.td,{children:"What actually changed, and what did we check?"}),(0,s.jsx)(t.td,{children:"The diff and the verification output"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:(0,s.jsx)(t.strong,{children:"Rollback"})}),(0,s.jsx)(t.td,{children:"If this is wrong in prod, how do we undo it?"}),(0,s.jsxs)(t.td,{children:["The ",(0,s.jsx)(t.code,{children:"rollback"})," line from the contract"]})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:(0,s.jsx)(t.strong,{children:"Residual risk"})}),(0,s.jsx)(t.td,{children:"What could still go wrong that the checks don't cover?"}),(0,s.jsxs)(t.td,{children:["Your honest read of what the tests ",(0,s.jsx)(t.em,{children:"don't"})," prove"]})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:(0,s.jsx)(t.strong,{children:"Cost receipt"})}),(0,s.jsx)(t.td,{children:"What did this run cost, and was it staffed right?"}),(0,s.jsx)(t.td,{children:"The Agent Run Ledger from Module 4"})]})]})]}),"\n",(0,s.jsxs)(t.p,{children:["The first three are objective: the suite passed, here is the diff, here is the undo command. The last two are where judgment lives. ",(0,s.jsx)(t.strong,{children:"Residual risk"})," is you stating what the green checks do ",(0,s.jsx)(t.em,{children:"not"}),' prove: the tests pass, but they do not exercise the endpoint under load, so latency under concurrency is unproven. Naming that is not admitting weakness; it is the difference between "it\'s done" and "it\'s done, and here is exactly what we\'re still trusting." ',(0,s.jsx)(t.strong,{children:"Cost receipt"})," closes the loop back to Module 4: the run itself is evidence, and a task that shipped without a record of what it cost is a task you cannot account for later."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Analogy:"}),' this is a pre-flight and post-flight logbook, not a thumbs-up. A pilot who lands does not just say "we made it." The logbook records the flight, the fuel burned, anything that behaved oddly, and the state the aircraft is in for the next crew. That record is what makes the operation ',(0,s.jsx)(t.em,{children:"accountable"})," rather than merely ",(0,s.jsx)(t.em,{children:"successful"}),": the next person can trust the aircraft because the last flight is documented, not because someone vouched for it. A finished agent task is a logbook entry: what it did, proof it worked, how to undo it, what is still uncertain, and what it cost."]}),"\n",(0,s.jsx)(t.h2,{id:"what-youll-do-in-the-lab",children:"What you'll do in the lab"}),"\n",(0,s.jsxs)(t.p,{children:["You will run one small, low-risk change end to end under the full contract. You will write a task contract for adding a ",(0,s.jsx)(t.code,{children:"/version"})," endpoint to orders-api: intent, target, allowed and denied actions, acceptance criteria, stop conditions, and rollback. You will create a git worktree so the work happens off ",(0,s.jsx)(t.code,{children:"main"}),". You will run Claude Code in plan mode and review the plan against your contract before a single file is edited. You will switch to execution and let the agent make the change inside the worktree. Then you will let the ",(0,s.jsx)(t.em,{children:"repository"})," decide it is done: run the existing tests, the new test, and ",(0,s.jsx)(t.code,{children:"grade.sh"}),", and deliberately compare that deterministic verdict against what agent self-assessment tells you, so you can see exactly where inference and evidence diverge. You will assemble the definition-of-done record: diff, test output, rollback, residual risk, and the cost receipt from Module 4's ledger, and finally tear the worktree down, leaving ",(0,s.jsx)(t.code,{children:"main"})," exactly as it started."]}),"\n",(0,s.jsxs)(t.p,{children:["Module 1 taught you the loop as a habit. This module makes it an ",(0,s.jsx)(t.em,{children:"auditable procedure"}),": a contract you agreed before, a plan you approved before, an isolated place you ran it, a repository that decided it was done, and a record you can defend after. The Deep Dive then goes under the hood of the two things the lab treated as tools: how ",(0,s.jsx)(t.code,{children:"/verify"})," inference actually works and exactly when it helps versus when it quietly lies, and how the ",(0,s.jsx)(t.code,{children:"/goal"})," command lets an agent drive toward an objective while still checking itself against something real."]})]})}function u(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(l,{...e})}):l(e)}},7684(e,t,n){n.d(t,{A:()=>i});var a=n(4848);n(6540);var s=n(6497);function i({src:e,title:t="Slides"}){let n=(0,s.Ay)(e);return(0,a.jsxs)("div",{className:"deck_nWXz",children:[(0,a.jsxs)("div",{className:"bar_dOoE",children:[(0,a.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",t]}),(0,a.jsx)("a",{className:"full_PrDQ",href:n,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,a.jsx)("div",{className:"frame_M4DO",children:(0,a.jsx)("iframe",{src:n,title:t,loading:"lazy",allowFullScreen:!0})})]})}},8453(e,t,n){n.d(t,{R:()=>o,x:()=>r});var a=n(6540);let s={},i=a.createContext(s);function o(e){let t=a.useContext(i);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),a.createElement(i.Provider,{value:t},e.children)}}}]);